#!/usr/bin/env python3
"""Apply Ksign's reviewed overlays to the pinned IDeviceKit submodule.

Bounded uploads and buffer-lifetime fixes are included in InstallationProxy.
Unknown inputs fail before any writes. Edit Native/Device,
then rerun this script to refresh generated files for local and CI builds.
"""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[2]
TEMPLATES = ROOT / "Native/Device"
MARKER = "// Generated by Ksign's integrate_devicekit.py; edit Native/Device instead.\n"


def replace_once(source, old, new):
    if source.count(old) != 1:
        raise RuntimeError(f"Expected one upstream match for {old[:70]!r}")
    return source.replace(old, new, 1)


def transform(inputs):
    outputs = dict(inputs)
    source = inputs["Package.swift"]
    start = source.index('\t\t\turl: "https://github.com/jkcoxson/idevice/')
    end = source.index('\n\t\t)', start)
    outputs["Package.swift"] = source[:start] + '\t\t\tpath: ".build/IDevice.xcframework"' + source[end:]

    key = "Sources/IDeviceSwift/Heartbeat/Heartbeat.swift"
    source = replace_once(inputs[key], '\t\tFileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!.appendingPathComponent("pairingFile.plist").relativePath',
                          '\t\tconfiguredPairingPath ?? FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!.appendingPathComponent("pairingFile.plist").relativePath')
    source = source.replace('\t\tidevice_init_logger(IdeviceLogLevel.init(3), Disabled, nil)', '\t\t// Native debug logging can expose pairing keys; keep it disabled.')
    outputs[key] = source

    key = "Sources/IDeviceSwift/Heartbeat/Heartbeat+start.swift"
    source = inputs[key]
    start = source.index('\tprivate static var _adapter:')
    end = source.index('\t// MARK: - Start\n', start)
    source = source[:start] + source[end:]
    source = replace_once(source, '\t\t\tadapter = nil\n\t\t\thandshake = nil', '\t\t\tinvalidateRSDTunnel()')
    start = source.index('\tinternal func ensureRSDTunnel()')
    end = source.index('\t// MARK: - Start Heartbeat', start)
    source = source[:start] + '''\tinternal func ensureRSDTunnel() -> Bool {
\t\tdo { _ = try acquireRSDConnection(); return true }
\t\tcatch { return false }
\t}

''' + source[end:]
    outputs[key] = source

    key = "Sources/IDeviceSwift/IDeviceSwiftError.swift"
    outputs[key] = replace_once(inputs[key], 'struct IDeviceSwiftError: Error {',
        'struct IDeviceSwiftError: LocalizedError {\n\tvar errorDescription: String? { _message }')

    # Keep leases for the complete lifetime of auxiliary clients too.
    key = "Sources/IDeviceSwift/InstallationProxy/InstallationAppProxy.swift"
    source = inputs[key]
    anchor = '\t\tlet allApps = try await Task.detached(priority: .userInitiated) { () -> [AppInfo] in'
    source = replace_once(source, anchor, anchor + '\n\t\t\tlet connection = self._heartbeat.isRsd ? try self._heartbeat.acquireRSDConnection() : nil\n\t\t\tdefer { withExtendedLifetime(connection) {} }')
    source = replace_once(source,
        'installation_proxy_connect_rsd(self._heartbeat.adapter, self._heartbeat.handshake, &installproxy)',
        'connection?.withServiceConnection { adapter, handshake in installation_proxy_connect_rsd(adapter, handshake, &installproxy) }')
    start = source.index('\tstatic public func getAppIcon(for id: String) async throws -> UIImage? {')
    before, icon = source[:start], source[start:]
    needle = '\t\treturn try await Task.detached(priority: .userInitiated) {'
    icon = replace_once(icon, needle, needle + '\n\t\t\tlet connection = HeartbeatManager.shared.isRsd ? try HeartbeatManager.shared.acquireRSDConnection() : nil\n\t\t\tdefer { withExtendedLifetime(connection) {} }')
    icon = replace_once(icon,
        'springboard_services_connect_rsd(HeartbeatManager.shared.adapter, HeartbeatManager.shared.handshake, &springServices)',
        'connection?.withServiceConnection { adapter, handshake in springboard_services_connect_rsd(adapter, handshake, &springServices) }')
    outputs[key] = before + icon

    key = "Sources/IDeviceSwift/Trace/SystemLogManager.swift"
    source = inputs[key]
    source = source.replace('try await self._connect()', 'try await self._connect()\n\t\t\tlet connection = self._heartbeat.isRsd ? try self._heartbeat.acquireRSDConnection() : nil\n\t\t\tdefer { withExtendedLifetime(connection) {} }')
    handles = '''\t\t\t\tguard let adapter = self._heartbeat.adapter else {
\t\t\t\t\tthrow IDeviceSwiftError(message: "Cannot find RSD adapter")
\t\t\t\t}
\t\t\t\t
\t\t\t\tguard let handshake = self._heartbeat.handshake else {
\t\t\t\t\tthrow IDeviceSwiftError(message: "Cannot find RSD handshake")
\t\t\t\t}'''
    if source.count(handles) != 2:
        raise RuntimeError("Expected two upstream trace connection blocks")
    source = source.replace(handles, '''\t\t\t\tguard let connection else {
\t\t\t\t\tthrow IDeviceSwiftError(message: "Cannot find RSD connection")
\t\t\t\t}''')
    for function, client in (("syslog_relay_connect_rsd", "syslogClient"),
                             ("os_trace_relay_connect_rsd", "osTraceRelayClient")):
        call = f"{function}(adapter, handshake, &self.{client})"
        source = replace_once(source, call,
            f"connection.withServiceConnection {{ adapter, handshake in {call} }}")
    outputs[key] = source

    for name, destination in {
        "InstallationProxy.swift": "InstallationProxy/InstallationProxy.swift",
        "InstallerStatusViewModel.swift": "InstallationProxy/InstallerStatusViewModel.swift",
        "RSDConnection.swift": "Heartbeat/RSDConnection.swift",
        "IDeviceInstallationWorker.swift": "InstallationProxy/IDeviceInstallationWorker.swift",
    }.items():
        outputs["Sources/IDeviceSwift/" + destination] = (TEMPLATES / name).read_text()
    return outputs


def apply(kit):
    checksums = json.loads((TEMPLATES / "swift-inputs.json").read_text())
    inputs = {}
    for relative, accepted in checksums.items():
        source = (kit / relative).read_text()
        if MARKER in source[:200]:
            source = subprocess.check_output(["git", "-C", str(kit), "show", f"HEAD:{relative}"], text=True)
        if hashlib.sha256(source.encode()).hexdigest() not in accepted:
            raise RuntimeError(f"Unrecognized IDeviceKit source: {relative}; review overlays before updating the submodule.")
        inputs[relative] = source
    outputs = transform(inputs)
    for relative, source in outputs.items():
        path = kit / relative
        if relative == "Package.swift":
            first, rest = source.split('\n', 1)
            source = first + '\n' + MARKER + rest
        else:
            source = MARKER + source
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(source)
    print("Applied Ksign device installation overlays")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--kit", type=Path, default=ROOT / "IDeviceKit")
    apply(parser.parse_args().kit)
